package dev.henrique.inventory;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.springframework.test.web.servlet.MockMvc; import org.testcontainers.containers.PostgreSQLContainer; import org.testcontainers.junit.jupiter.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @Testcontainers class ApiIntegrationTest { @Container static final PostgreSQLContainer<?> DB=new PostgreSQLContainer<>("postgres:17-alpine"); @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::getJdbcUrl);r.add("spring.datasource.username",DB::getUsername);r.add("spring.datasource.password",DB::getPassword);}@Autowired MockMvc mvc;
 @Test void blankProductIsStructuredValidationError() throws Exception {mvc.perform(post("/api/products").contentType("application/json").content("{\"sku\":\"\",\"name\":\"\"}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED")).andExpect(jsonPath("$.details.sku").exists());}
 @Test void malformedIdentifierIsBadRequest() throws Exception {mvc.perform(get("/api/products/not-a-uuid")).andExpect(status().isBadRequest());}
}
